import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Sovereign Edge — Development Workflow","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/development-workflow.md"},"headers":[],"relativePath":"sovereign-edge/development-workflow.md","filePath":"sovereign-edge/development-workflow.md"}'),d={name:"sovereign-edge/development-workflow.md"};function n(r,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="sovereign-edge-—-development-workflow" tabindex="-1">Sovereign Edge — Development Workflow <a class="header-anchor" href="#sovereign-edge-—-development-workflow" aria-label="Permalink to &quot;Sovereign Edge — Development Workflow&quot;">​</a></h1><p>How tasks are planned, started, implemented, and closed out. Designed for agentic execution with human oversight.</p><p>Adapted from <code>sovereign</code>&#39;s <code>docs/development-workflow.md</code>. The shape is the same so that moving between ecosystem repos does not mean relearning it; the parts that presuppose a monorepo, an SRS, or <code>sovereign</code>&#39;s <code>/sv-*</code> skills are deliberately not carried over — see <a href="#not-adopted-yet">Not adopted</a>.</p><hr><h2 id="three-layer-information-architecture" tabindex="-1">Three-layer information architecture <a class="header-anchor" href="#three-layer-information-architecture" aria-label="Permalink to &quot;Three-layer information architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AGENTS.md (root) / CLAUDE.md   ← shared conventions and hard rules; no task pointer</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─▶ apps/mobile/AGENTS.md  ← mobile-only: commands, native build mechanics,</span></span>
<span class="line"><span>    │                             environment quirks, current implementation state</span></span>
<span class="line"><span>    ├─▶ apps/desktop/AGENTS.md ← same, for desktop — real since task 12.1</span></span>
<span class="line"><span>    │                             (Tauri scaffold); most of epic 12 still stub</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └─▶ ROADMAP.md             ← chronological index; one row per task; canonical status</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            └─▶ docs/epics/{mobile,desktop,shared}/&lt;epic&gt;.md</span></span>
<span class="line"><span>                                       ← full task detail: scope/status frontmatter,</span></span>
<span class="line"><span>                                          Goal, Deliverables, Dependencies, Review checklist</span></span></code></pre></div><p>Each layer has one job:</p><table tabindex="0"><thead><tr><th>File</th><th>Job</th><th>Read it for</th></tr></thead><tbody><tr><td><code>AGENTS.md</code> (root)</td><td>Shared conventions and hard rules</td><td>How to work here; what must never be violated, across any app or package</td></tr><tr><td><code>apps/*/AGENTS.md</code></td><td>Per-app conventions</td><td>Commands, native mechanics, environment quirks — never restates the root file</td></tr><tr><td><code>CLAUDE.md</code></td><td>Claude Code adapter</td><td>Nothing — it points at <code>AGENTS.md</code></td></tr><tr><td><code>ROADMAP.md</code></td><td>Version-ordered task index</td><td>Which tasks exist, their status, which epic file</td></tr><tr><td><code>docs/epics/{mobile,desktop,shared}/&lt;file&gt;.md</code></td><td>Full task spec</td><td><code>scope</code>/<code>status</code> frontmatter, goal, deliverables, review checklist</td></tr><tr><td><code>docs/research/&lt;n&gt;-*.md</code></td><td>Decision record</td><td>Why a settled question was settled that way</td></tr></tbody></table><p>There is no &quot;next task&quot; pointer in any of these. <strong>The developer assigns the next task at session start.</strong> A pointer in a doc goes stale the moment priorities shift, and two agents reading it would collide.</p><hr><h2 id="epic-structure" tabindex="-1">Epic structure <a class="header-anchor" href="#epic-structure" aria-label="Permalink to &quot;Epic structure&quot;">​</a></h2><p>Work is organised into domain epics, indexed in <a href="./epics/README.html"><code>docs/epics/README.md</code></a>. Each task carries a <strong>stable epic task ID</strong> (<code>&lt;epic&gt;.&lt;seq&gt;</code>).</p><h3 id="stable-ids-vs-volatile-slots" tabindex="-1">Stable IDs vs volatile slots <a class="header-anchor" href="#stable-ids-vs-volatile-slots" aria-label="Permalink to &quot;Stable IDs vs volatile slots&quot;">​</a></h3><p><strong>Epic task IDs are permanent.</strong> Once <code>0.4</code> is assigned it never changes. Use epic task IDs in doc cross-references and dependency lists — <code>ROADMAP.md</code>&#39;s Epic task column, review checklists, other epics&#39; Dependencies. <strong>Not</strong> in commit subjects, PR titles, or PR descriptions — matching <code>sovereign</code>&#39;s convention, work there is described by what it changes, not by a task number a reader may not have <code>docs/epics/</code> open to resolve.</p><p><strong>Roadmap slot versions are volatile.</strong> A slot like <code>0.1.4</code> reflects current priority ordering and shifts when work is reprioritised. Look the live slot up in <code>ROADMAP.md</code> rather than copying it into another document, and keep slots out of branch names and commit subjects — a stale slot reference is worse than none, because it looks authoritative.</p><hr><h2 id="task-lifecycle" tabindex="-1">Task lifecycle <a class="header-anchor" href="#task-lifecycle" aria-label="Permalink to &quot;Task lifecycle&quot;">​</a></h2><h3 id="starting-a-task" tabindex="-1">Starting a task <a class="header-anchor" href="#starting-a-task" aria-label="Permalink to &quot;Starting a task&quot;">​</a></h3><ol><li>The developer names the task (epic task ID or description).</li><li>Confirm <code>main</code> is clean and up to date: <code>git switch main &amp;&amp; git pull</code>.</li><li>Look up the epic file via <a href="./epics/README.html"><code>docs/epics/README.md</code></a> and read the full task block — goal, deliverables, dependencies, review checklist.</li><li>Read any research doc the task references. If the task turns on an unanswered architectural question, <strong>write the research doc first.</strong></li><li>Cut the branch: <code>feat/&lt;slug&gt;</code>, <code>fix/&lt;slug&gt;</code>, <code>docs/&lt;slug&gt;</code>, or <code>chore/&lt;slug&gt;</code>.</li></ol><h3 id="during-implementation" tabindex="-1">During implementation <a class="header-anchor" href="#during-implementation" aria-label="Permalink to &quot;During implementation&quot;">​</a></h3><ul><li><strong>One task at a time.</strong> Do not start a task on an unmerged PR.</li><li>Commit as you go, with messages that explain <em>why</em>.</li><li>When something you assumed turns out to be wrong, say so in the same turn rather than quietly correcting course — the correction is usually the most useful information in the update.</li></ul><h3 id="completing-a-task" tabindex="-1">Completing a task <a class="header-anchor" href="#completing-a-task" aria-label="Permalink to &quot;Completing a task&quot;">​</a></h3><ol><li><strong>Verify.</strong> Run <code>pnpm format:check</code>, <code>pnpm lint</code>, <code>pnpm typecheck</code>, <code>pnpm test</code> — and then actually exercise the change (see below).</li><li><strong>Update status.</strong> Mark the task ✅ in <code>ROADMAP.md</code> <em>and</em> the matching <code>docs/epics/&lt;file&gt;.md</code> heading, in the same PR.</li><li><strong>Bump the version</strong> — root <code>package.json</code> (and <code>ROADMAP.md</code>&#39;s header) to the roadmap slot just completed; the shipping app&#39;s own <code>package.json</code> (<code>apps/mobile/package.json</code> today) to its own release version, then run <code>pnpm prebuild</code> there so the native projects pick it up. See <a href="./../CONTRIBUTING.html#pull-requests">CONTRIBUTING.md</a> and <a href="./../apps/mobile/AGENTS.html">apps/mobile/AGENTS.md</a> for the app&#39;s four-file agreement and why the prebuild step is not optional.</li><li><strong>Record decisions.</strong> If the task settled an open question, write or update the research doc and add it to <code>docs/research/README.md</code>.</li><li><strong>Open a draft PR</strong> with <code>gh pr create --draft</code>. Mark it ready for review only on explicit instruction, and <strong>never merge automatically.</strong> When the developer has instead asked for a direct commit to <code>main</code>, steps 1–4 are unchanged; only this step differs.</li></ol><hr><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Running the checks is necessary but not sufficient. The review checklist in each epic describes an observable behaviour, and that is the thing to demonstrate.</p><p>Two failures in this repo passed a fully green suite:</p><ul><li><strong>A stall watchdog reported the wrong error code.</strong> Calling <code>pauseAsync()</code> makes the in-flight <code>downloadAsync()</code> resolve <code>null</code>, which won a <code>Promise.race</code> and surfaced as <code>code: &#39;network&#39;</code> instead of <code>&#39;stalled&#39;</code> — hiding both the true cause and the fact that the transfer was resumable. The unit test mocked the download as never-resolving, so the race could not occur there.</li><li><strong><code>expo prebuild</code> exits 0 when its internal <code>pod install</code> fails.</strong> The missing <code>.xcworkspace</code> only surfaces later as a confusing <code>xcodebuild</code> error.</li></ul><p>The lesson both times: <strong>check the artefact, not the exit code</strong>, and drive the real path. App launch is verified by the <code>Native build</code> workflow on a simulator and emulator; the model pipeline was verified against a local HTTP origin supporting Range requests, throttling, and a deliberate stall.</p><hr><h2 id="status-tracking" tabindex="-1">Status tracking <a class="header-anchor" href="#status-tracking" aria-label="Permalink to &quot;Status tracking&quot;">​</a></h2><p>Status lives in exactly two places:</p><table tabindex="0"><thead><tr><th>Location</th><th>Tracks</th></tr></thead><tbody><tr><td><code>ROADMAP.md</code> row Status cell</td><td>✅ / ⏳ / 📋 per task — the canonical record</td></tr><tr><td>Open PRs</td><td>Which tasks are currently in flight</td></tr></tbody></table><p>Epic file headings (<code>#### ✅ X.Y — …</code>) are updated when a task completes. Close a task by marking <strong>both</strong> the roadmap row and the epic heading in the same PR.</p><p>Do not accumulate completion history in <code>AGENTS.md</code> or <code>CLAUDE.md</code>. Git log already records what happened, and a hand-maintained changelog inside a conventions file drifts — <code>sovereign/CLAUDE.md</code> is the cautionary example.</p><hr><h2 id="research-docs" tabindex="-1">Research docs <a class="header-anchor" href="#research-docs" aria-label="Permalink to &quot;Research docs&quot;">​</a></h2><p>A research doc captures an open-ended question that has no committed design yet: findings, options considered, and a recommendation. Lighter than a design doc, and kept after the decision lands — it is the working record of <em>why</em>.</p><ul><li>Write one <strong>before</strong> building on an unverified assumption.</li><li>&quot;Rejected&quot; and &quot;not now&quot; are valid, useful outcomes.</li><li>Add a row to <a href="./research/README.html"><code>docs/research/README.md</code></a> when you add a doc.</li><li>When a later measurement overturns a recorded decision, <strong>update the doc</strong> rather than leaving a contradiction between the docs and the code.</li></ul><p>This repo has no RFC stage. If one is ever added, the connector manifest schema is the first thing that should be formalised that way.</p><hr><h2 id="not-adopted-yet" tabindex="-1">Not adopted (yet) <a class="header-anchor" href="#not-adopted-yet" aria-label="Permalink to &quot;Not adopted (yet)&quot;">​</a></h2><p><code>sovereign</code>&#39;s workflow includes machinery this repo does not need at its current size. Recorded here so the divergence is deliberate rather than an oversight:</p><table tabindex="0"><thead><tr><th>Not adopted</th><th>Why</th></tr></thead><tbody><tr><td><code>CURRENT_TASK.md</code></td><td>A transient task-scratch file written and deleted by <code>/sv-*</code> skills that do not exist here</td></tr><tr><td><code>/sv-task-start</code> etc.</td><td><code>sovereign</code>-specific skills bound to its monorepo layout</td></tr><tr><td>Workstreams and legs</td><td>A batching unit for multi-task features; this roadmap is still one task at a time</td></tr><tr><td>SRS references</td><td>There is no SRS. Research docs and epic files carry the requirement detail</td></tr><tr><td><code>docs-parity</code> test</td><td>Enforces doc coverage of a manifest/SDK surface that does not exist yet — revisit at epic 5 (SDK)</td></tr></tbody></table><p>Revisit these when the repo outgrows the simpler model, not before.</p><p><strong>Per-package version bumps — adopted</strong>, since the workspace restructure outgrew the single-<code>package.json</code> model this table used to defer. Root <code>package.json</code>&#39;s version tracks the roadmap slot of the last completed task (mirrors <code>sovereign</code>&#39;s own root-version convention: <code>ROADMAP.md</code>&#39;s header reads from it); each app under <code>apps/*</code> carries its own release version, bumped independently in that app&#39;s own <code>package.json</code> when it ships something. Release tags follow <code>sovereign</code>&#39;s <code>&lt;slug&gt;-vX.Y.Z</code> pattern — <code>mobile-vX.Y.Z</code> today, <code>desktop-vX.Y.Z</code> once that app exists. The two versions move in lockstep for now because every completed task is still a mobile task; they&#39;re expected to diverge once desktop tasks are scheduled too.</p><hr><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I need to know…</th><th>Read…</th></tr></thead><tbody><tr><td>What task is next</td><td>Ask the developer; <code>ROADMAP.md</code> lists what is pending</td></tr><tr><td>Full spec for a task by epic ID</td><td><code>docs/epics/&lt;file&gt;.md</code> — grep for <code>^#### .*&lt;id&gt;</code></td></tr><tr><td>All tasks in a domain</td><td><code>docs/epics/&lt;file&gt;.md</code></td></tr><tr><td>Which epic a roadmap task belongs to</td><td><code>ROADMAP.md</code> → Epic task column</td></tr><tr><td>Epic file for a given epic ID</td><td><code>docs/epics/README.md</code></td></tr><tr><td>Why a decision was made</td><td><code>docs/research/</code> — index at <code>docs/research/README.md</code></td></tr><tr><td>Shared conventions and hard rules</td><td><code>AGENTS.md</code> (root)</td></tr><tr><td>Mobile/desktop commands, quirks</td><td><code>apps/mobile/AGENTS.md</code> / <code>apps/desktop/AGENTS.md</code></td></tr><tr><td>Setup, branching, commits, PRs, CI</td><td><code>CONTRIBUTING.md</code></td></tr></tbody></table>`,49)])])}const u=t(d,[["render",n]]);export{m as __pageData,u as default};
